package com.bank.qa.dedupe;

// One physical row: surrogate id + natural key account_no + some data.
class AccountRow {
    final int id;            // surrogate key (tie-break for survivor)
    final String accountNo;  // natural key that must be unique
    final String holder;
    AccountRow(int id, String accountNo, String holder) {
            this.id = id;
            this.accountNo = accountNo
            this.holder = holder;
    }
    @Override public String toString() { return "id=" + id + " acc=" + accountNo + " holder=" + holder; }
}
