package com.bank.qa.dedupe;

import java.util.*;
import java.util.logging.*;

public class DuplicateCleanupDemo {
    private static final Logger log = Logger.getLogger(DuplicateCleanupDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new DedupeLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        // SAV2001 duplicated 3x, CUR3001 duplicated 2x, SAV7777 unique
        List<AccountRow> rows = new ArrayList<>(List.of(
            new AccountRow(1, "SAV2001", "Rajesh Kumar"),
            new AccountRow(2, "SAV2001", "Rajesh Kumar"),
            new AccountRow(3, "SAV2001", "Rajesh Kumar"),
            new AccountRow(4, "CUR3001", "Priya Sharma"),
            new AccountRow(5, "CUR3001", "Priya Sharma"),
            new AccountRow(6, "SAV7777", "New Customer")
        ));

        DuplicateCleaner cleaner = new DuplicateCleaner();

        log.info("=== Step 1: find duplicates (GROUP BY ... HAVING COUNT>1) ===");
        cleaner.findDuplicates(rows).forEach((k, c) -> log.info("DUPLICATE account_no=" + k + " copies=" + c));

        log.info("=== Step 2: backup + delete keeping MIN id (in a transaction) ===");
        List<AccountRow> backup = new ArrayList<>();
        List<AccountRow> cleaned = cleaner.deleteKeepingMinId(rows, backup);
        log.info("Backup rows saved: " + backup.size());

        log.info("=== Step 3: verify + show survivors ===");
        cleaner.verify(cleaned);
        cleaned.forEach(r -> log.info("SURVIVOR " + r));
    }
}

